import json, sys

def trunc(s, n=300):
    s = str(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"

def content_repr(content):
    if isinstance(content, str):
        return trunc(content)
    if isinstance(content, list):
        parts = []
        for c in content:
            if not isinstance(c, dict):
                parts.append(trunc(c))
                continue
            t = c.get('type')
            if t == 'text':
                parts.append(f"[text] {trunc(c.get('text',''))}")
            elif t == 'tool_use':
                parts.append(f"[tool_use:{c.get('name')}] {trunc(json.dumps(c.get('input',{})))}")
            elif t == 'tool_result':
                cc = c.get('content')
                parts.append(f"[tool_result err={c.get('is_error')}] {trunc(cc)}")
            elif t == 'thinking':
                parts.append(f"[thinking] {trunc(c.get('thinking',''))}")
            else:
                parts.append(f"[{t}] {trunc(c)}")
        return " || ".join(parts)
    return trunc(content)

fn = sys.argv[1]
with open(fn) as f:
    for i, line in enumerate(f):
        line = line.strip()
        if not line:
            continue
        try:
            d = json.loads(line)
        except Exception as e:
            print(f"{i}: PARSE ERROR {e}")
            continue
        ts = d.get('timestamp','')
        typ = d.get('type','')
        if typ == 'attachment':
            continue
        msg = d.get('message', {})
        role = msg.get('role','')
        content = msg.get('content')
        rep = content_repr(content) if content is not None else ''
        print(f"[{i}] {ts} {typ}/{role}: {rep}")

import json, sys

def text_of(content):
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for c in content:
            if not isinstance(c, dict):
                continue
            t = c.get('type')
            if t == 'text':
                parts.append(c.get('text',''))
            elif t == 'tool_use':
                inp = json.dumps(c.get('input',{}))[:500]
                parts.append(f"[TOOL_USE {c.get('name')} input={inp}]")
            elif t == 'tool_result':
                cont = c.get('content')
                if isinstance(cont, list):
                    sub = []
                    for cc in cont:
                        if isinstance(cc, dict) and cc.get('type')=='text':
                            sub.append(cc.get('text',''))
                    cont = '\n'.join(sub)
                cont = (cont or '')
                parts.append(f"[TOOL_RESULT {str(cont)[:600]}]")
            elif t == 'image':
                parts.append('[IMAGE]')
            else:
                parts.append(f"[{t}]")
        return '\n'.join(parts)
    return str(content)

def main(path, outpath):
    with open(path) as f, open(outpath, 'w') as out:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            typ = d.get('type')
            ts = d.get('timestamp', '')
            if typ in ('user', 'assistant'):
                msg = d.get('message', {})
                role = msg.get('role', typ)
                content = msg.get('content')
                txt = text_of(content)
                if not txt.strip():
                    continue
                out.write(f"=== [{ts}] {role} ===\n{txt[:2000]}\n\n")
            elif typ == 'queue-operation':
                out.write(f"=== [{ts}] QUEUE {d.get('operation')} ===\n{str(d.get('content',''))[:300]}\n\n")

if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])

