import json, sys

def trunc(s, n=300):
    s = str(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"

def summarize_content(content):
    out = []
    if isinstance(content, str):
        out.append(("text", trunc(content, 500)))
    elif isinstance(content, list):
        for c in content:
            if not isinstance(c, dict):
                out.append(("?", trunc(c)))
                continue
            t = c.get("type")
            if t == "text":
                out.append(("text", trunc(c.get("text",""), 500)))
            elif t == "tool_use":
                out.append(("tool_use", c.get("name"), trunc(c.get("input"), 400)))
            elif t == "tool_result":
                cont = c.get("content")
                if isinstance(cont, list):
                    txt = " ".join(x.get("text","") for x in cont if isinstance(x, dict))
                else:
                    txt = str(cont)
                out.append(("tool_result", "err" if c.get("is_error") else "ok", trunc(txt, 400)))
            else:
                out.append((t, trunc(c, 300)))
    return out

path = sys.argv[1]
with open(path) as f:
    for i, line in enumerate(f):
        line = line.strip()
        if not line:
            continue
        try:
            d = json.loads(line)
        except Exception as e:
            print(f"[{i}] JSON ERROR {e}")
            continue
        typ = d.get("type")
        ts = d.get("timestamp","")
        if typ == "user" or typ == "assistant":
            msg = d.get("message", {})
            role = msg.get("role", typ)
            content = msg.get("content")
            summ = summarize_content(content)
            print(f"[{i}] {ts} {role}:")
            for s in summ:
                print("    ", s)
        elif typ in ("summary",):
            print(f"[{i}] {ts} SUMMARY: {trunc(d)}")
        else:
            pass

